#include <stdio.h>
#include <stdlib.h>

int create_value(int **out) {
    if (out == NULL) return 0;
    *out = malloc(sizeof **out);
    if (*out == NULL) return 0;
    **out = 75;
    return 1;
}

int main(void) {
    int *value = NULL;
    if (!create_value(&value)) return 1;
    printf("%d\n", *value);
    free(value);
    return 0;
}
